-- 132: Original BrillaPrep WASSCE BrillaPrep transitional Applied Electricity beta content blueprint beta questions, part 3.
-- Curriculum-aligned practice content; not official WAEC examination material.
PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS _migration_132_guard (valid INTEGER NOT NULL CHECK (valid = 1));
DELETE FROM _migration_132_guard;
INSERT INTO _migration_132_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_011' AND NOT (q.topic_id IS 'topic_was_elect_3' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What does a capacitor store?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. A continuous supply of fuel","B. Only magnetic poles","C. Electric charge and energy in an electric field","D. Mechanical torque without a field"]' AND q.correct_answer IS 'C' AND q.explanation IS 'Separated conductors and a dielectric allow charge to accumulate, with energy stored in the electric field between them. Therefore the correct answer is C: Electric charge and energy in an electric field.' AND q.difficulty IS 'medium' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_011' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_132_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_012' AND NOT (q.topic_id IS 'topic_was_elect_3' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'A capacitor is marked 470 µF. Which named SI unit does the letter F represent?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. Henry","B. Weber","C. Tesla","D. Farad"]' AND q.correct_answer IS 'D' AND q.explanation IS 'Capacitance is charge stored per unit potential difference and is measured in farads, commonly expressed in microfarads or smaller units. Therefore the correct answer is D: Farad.' AND q.difficulty IS 'hard' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_012' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_132_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_013' AND NOT (q.topic_id IS 'topic_was_elect_3' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'How does capacitive reactance change when frequency increases?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It decreases","B. It increases linearly","C. It remains constant","D. It becomes resistance only"]' AND q.correct_answer IS 'A' AND q.explanation IS 'Capacitive reactance is Xc = 1 divided by 2πfC, so higher frequency produces less opposition from a given capacitor. Therefore the correct answer is A: It decreases.' AND q.difficulty IS 'easy' AND q.points IS '1' AND q.marks IS '1' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO1' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_013' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_132_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_014' AND NOT (q.topic_id IS 'topic_was_elect_3' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'What is impedance in an alternating-current circuit?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. The direct-current charge of a battery","B. The combined opposition of resistance and reactance","C. Only the physical size of a conductor","D. Power multiplied by time"]' AND q.correct_answer IS 'B' AND q.explanation IS 'Impedance accounts for resistance and frequency-dependent reactance and is represented in ohms, often with magnitude and phase. Therefore the correct answer is B: The combined opposition of resistance and reactance.' AND q.difficulty IS 'medium' AND q.points IS '2' AND q.marks IS '2' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_3' AND q.command_word IS 'Identify' AND q.assessment_objective IS 'AO2' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_014' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT INTO _migration_132_guard(valid) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM questions q WHERE q.id = 'q_was_elect_b001_015' AND NOT (q.topic_id IS 'topic_was_elect_3' AND q.subject_id IS 'subj_wassce_elect_app' AND q.exam_type_id IS 'exam_wassce' AND q.paper_type_id IS NULL AND q.past_paper_id IS NULL AND q.question_text IS 'Why is a high power factor generally desirable for an AC load?' AND q.question_type IS 'multiple_choice' AND q.round_type IS NULL AND q.options IS '["A. It makes voltage and frequency irrelevant","B. It eliminates all energy loss","C. It reduces current required for a given real power","D. It causes every load to become capacitive"]' AND q.correct_answer IS 'C' AND q.explanation IS 'When power factor is closer to unity, less current is needed to deliver the same useful power, reducing conductor and system losses. Therefore the correct answer is C: It reduces current required for a given real power.' AND q.difficulty IS 'hard' AND q.points IS '3' AND q.marks IS '3' AND q.time_limit IS '90' AND q.question_number IS NULL AND q.section IS NULL AND q.is_compulsory IS '1' AND q.image_url IS NULL AND q.syllabus_topic_id IS 'st_was_elect_3' AND q.command_word IS 'Explain' AND q.assessment_objective IS 'AO3' AND q.source_paper_code IS NULL AND q.source_question_number IS NULL AND q.exam_board_id IS 'board_waec')) AND NOT EXISTS (SELECT 1 FROM question_content_releases r WHERE r.question_id = 'q_was_elect_b001_015' AND NOT (r.batch_id IS 'wassce-expansion-beta-001' AND r.quality_assurance IS 'automated_beta' AND r.release_channel IS 'beta' AND r.content_label IS 'Original BrillaPrep transitional Applied Electricity practice; not official WAEC examination material and not the new Applied Technology III bank.' AND r.source_url IS 'https://waecgh.org/wp-content/uploads/2026/03/FINAL-TIMETABLE-FOR-WASSCE-SC-2026-GHANA-ONLY-NEW-TAD.pdf' AND r.official_exam_board_content IS 0 AND r.feedback_enabled IS 1)) THEN 1 ELSE 0 END;
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_elect_b001_011', 'topic_was_elect_3', 'subj_wassce_elect_app', 'exam_wassce', NULL, NULL, 'What does a capacitor store?', 'multiple_choice', NULL, '["A. A continuous supply of fuel","B. Only magnetic poles","C. Electric charge and energy in an electric field","D. Mechanical torque without a field"]', 'C', 'Separated conductors and a dielectric allow charge to accumulate, with energy stored in the electric field between them. Therefore the correct answer is C: Electric charge and energy in an electric field.', 'medium', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_elect_3', 'Identify', 'AO2', NULL, NULL, 'board_waec');
