INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_elect_b001_013', 'topic_was_elect_3', 'subj_wassce_elect_app', 'exam_wassce', NULL, NULL, 'How does capacitive reactance change when frequency increases?', 'multiple_choice', NULL, '["A. It decreases","B. It increases linearly","C. It remains constant","D. It becomes resistance only"]', 'A', 'Capacitive reactance is Xc = 1 divided by 2πfC, so higher frequency produces less opposition from a given capacitor. Therefore the correct answer is A: It decreases.', 'easy', '1', '1', '90', NULL, NULL, '1', NULL, 'st_was_elect_3', 'Explain', 'AO1', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_elect_b001_014', 'topic_was_elect_3', 'subj_wassce_elect_app', 'exam_wassce', NULL, NULL, 'What is impedance in an alternating-current circuit?', 'multiple_choice', NULL, '["A. The direct-current charge of a battery","B. The combined opposition of resistance and reactance","C. Only the physical size of a conductor","D. Power multiplied by time"]', 'B', 'Impedance accounts for resistance and frequency-dependent reactance and is represented in ohms, often with magnitude and phase. Therefore the correct answer is B: The combined opposition of resistance and reactance.', 'medium', '2', '2', '90', NULL, NULL, '1', NULL, 'st_was_elect_3', 'Identify', 'AO2', NULL, NULL, 'board_waec');
INSERT OR IGNORE INTO questions (id, topic_id, subject_id, exam_type_id, paper_type_id, past_paper_id, question_text, question_type, round_type, options, correct_answer, explanation, difficulty, points, marks, time_limit, question_number, section, is_compulsory, image_url, syllabus_topic_id, command_word, assessment_objective, source_paper_code, source_question_number, exam_board_id) VALUES ('q_was_elect_b001_015', 'topic_was_elect_3', 'subj_wassce_elect_app', 'exam_wassce', NULL, NULL, 'Why is a high power factor generally desirable for an AC load?', 'multiple_choice', NULL, '["A. It makes voltage and frequency irrelevant","B. It eliminates all energy loss","C. It reduces current required for a given real power","D. It causes every load to become capacitive"]', 'C', 'When power factor is closer to unity, less current is needed to deliver the same useful power, reducing conductor and system losses. Therefore the correct answer is C: It reduces current required for a given real power.', 'hard', '3', '3', '90', NULL, NULL, '1', NULL, 'st_was_elect_3', 'Explain', 'AO3', NULL, NULL, 'board_waec');
